package dev.homecontrol.app;

import android.app.Instrumentation;
import android.content.Context;
import android.os.Bundle;
import org.json.*;
import java.util.*;

/** Signed read-only device check. Never reports sessions/native DIDs or sends control commands. */
public final class MijiaDeviceCheckInstrumentation extends Instrumentation {
    private Bundle arguments;
    @Override public void onCreate(Bundle args){super.onCreate(args);arguments=args==null?new Bundle():args;start();}
    @Override public void onStart(){Bundle report=new Bundle();try{
        Context c=getTargetContext();JSONArray devices=DeviceStore.devices(c);Set<String> models=new TreeSet<>();int count=0,online=0,haier=0;JSONObject selected=null;String filter=arguments.getString("model","");
        for(int i=0;i<devices.length();i++){JSONObject d=devices.optJSONObject(i);if(d==null)continue;if("haier_cloud".equals(d.optString("source")))haier++;if(!"mijia_cloud".equals(d.optString("source")))continue;count++;models.add(d.optString("model"));if(d.optInt("state")==1){online++;boolean match=filter.isEmpty()?d.optString("model").contains(".light."):d.optString("model").equals(filter);if(selected==null&&match)selected=d;}}
        report.putInt("mijia_devices",count);report.putInt("mijia_online",online);report.putInt("haier_devices",haier);report.putString("models",new JSONArray(models).toString());report.putBoolean("logged_in",MijiaCloud.loggedIn(c));
        if("recipe_audit".equals(arguments.getString("mode")))recipeAudit(c,report);
        if("features".equals(arguments.getString("mode"))){
            String[] ops=arguments.getString("operations","recipes.home,recipes.search").split(",");JSONObject target=null;for(int i=0;i<devices.length();i++){JSONObject d=devices.optJSONObject(i);if(d!=null&&filter.equals(d.optString("model"))){target=d;break;}}if(target==null)throw new java.io.IOException("未找到目标型号");
            for(String op:ops){if(!Arrays.asList("kitchen.prepare","recipes.recommended","recipes.home","recipes.search","recipes.discover","recipes.detail","recipes.optional","recipes.favorites","light.delay.get","light.timers.list").contains(op))throw new java.io.IOException("检查器只允许读取");try{JSONObject args=new JSONObject().put("query","米饭").put("source",arguments.getString("source","detail")).put("recipeId",arguments.getString("recipeId","1")).put("menuType",arguments.getString("menuType","1"));Object raw=MijiaCloud.feature(c,target.getString("id"),op,args);report.putString(op+"_shape",shape(raw,0));report.putString(op+"_sample",sample(raw,0).toString());}catch(Exception e){report.putString(op+"_error",CloudDevices.error(e,"读取失败"));}}
        }
        if("kitchen_audit".equals(arguments.getString("mode"))){JSONObject target=null;for(int i=0;i<devices.length();i++){JSONObject d=devices.optJSONObject(i);if(d!=null&&filter.equals(d.optString("model"))){target=d;break;}}if(target==null)throw new java.io.IOException("未找到目标型号");JSONArray items=FeatureData.items(MijiaCloud.feature(c,target.getString("id"),"recipes.home",new JSONObject()),"modes");int prepared=0,containers=0;JSONArray details=new JSONArray();for(int i=0;i<Math.min(items.length(),40);i++){JSONObject item=items.getJSONObject(i);String name=item.optString("_title");if(item.optBoolean("isContainer")||item.optBoolean("isSelfChooseMode")||item.optBoolean("isSelfChoose")){containers++;JSONObject row=new JSONObject().put("name",name).put("container",true);try{JSONObject args=new JSONObject().put("containerId",item.optString("bussinessId",item.optString("_id")));JSONArray children=FeatureData.items(MijiaCloud.feature(c,target.getString("id"),"recipes.optional",args),"modes");row.put("children",children.length());JSONArray previews=new JSONArray();for(int ci=0;ci<Math.min(children.length(),2);ci++){JSONObject child=children.getJSONObject(ci);JSONObject args2=new JSONObject(args.toString()).put("source","optional").put("recipeId",child.getString("_id"));try{previews.put(MijiaCloud.feature(c,target.getString("id"),"kitchen.prepare",args2));}catch(Exception e){previews.put(new JSONObject().put("name",child.optString("_title")).put("error",CloudDevices.error(e,"读取失败")));}}row.put("previews",previews);}catch(Exception e){row.put("error",CloudDevices.error(e,"读取失败"));}details.put(row);continue;}JSONObject input=new JSONObject().put("recipeId",item.getString("_id")).put("source","home").put("menuType",item.optString("_menuType","1"));try{JSONObject draft=(JSONObject)MijiaCloud.feature(c,target.getString("id"),"kitchen.prepare",input);details.put(draft);prepared++;}catch(Exception e){details.put(new JSONObject().put("name",name).put("error",CloudDevices.error(e,"读取失败")));}}report.putInt("mode_count",items.length());report.putInt("prepared_count",prepared);report.putInt("container_count",containers);report.putString("mode_previews",details.toString());}
        if("read".equals(arguments.getString("mode"))){if(selected==null)throw new java.io.IOException("没有匹配的在线设备");JSONObject d=MijiaCloud.readDevice(c,selected.getString("id"));JSONArray caps=d.optJSONArray("capabilities");int readable=0,writable=0,known=0;if(caps!=null)for(int i=0;i<caps.length();i++){JSONObject p=caps.getJSONObject(i);if(p.optBoolean("readable"))readable++;if(p.optBoolean("writable"))writable++;if(p.has("value")&&!p.optBoolean("stale"))known++;}report.putString("read_device_name",d.optString("title"));report.putString("read_model",d.optString("model"));report.putInt("readable",readable);report.putInt("writable",writable);report.putInt("known_values",known);report.putInt("actions",d.optJSONArray("actions")==null?0:d.getJSONArray("actions").length());report.putString("device_state",d.optString("subtitle"));JSONArray states=new JSONArray();if(caps!=null)for(int i=0;i<caps.length();i++){JSONObject p=caps.getJSONObject(i);if(Arrays.asList("p:2:1","p:2:2","p:2:4","p:2:5","p:6:7").contains(p.optString("key")))states.put(new JSONObject().put("key",p.optString("key")).put("value",p.opt("value")).put("stale",p.optBoolean("stale")).put("readCode",p.opt("readCode")));}report.putString("read_values",states.toString());DeviceWidget.updateAll(c);}
        report.putBoolean("physical_commands_sent",false);finish(-1,report);
    }catch(Exception e){report.putString("error",CloudDevices.error(e,"设备读取检查未完成"));report.putBoolean("physical_commands_sent",false);finish(0,report);}}
    /** Fixed search-only path: cannot create collections, change menus or start cooking. */
    private void recipeAudit(Context c,Bundle report)throws Exception{
        try(MijiaVault vault=new MijiaVault(c)){
            JSONObject session=vault.read();MijiaCloud.validate(session);String base=MijiaWire.api(session.getString("region")),path="/eco/cm-microwaveoven/v2/index/search";JSONObject query=new JSONObject().put("keyword","米饭").put("pageNo",1).put("pageSize",3).put("model","xiaomi.microwave.cm20l").put("language","zh_CN");byte[] random=new byte[8];new java.security.SecureRandom().nextBytes(random);String nonce=MijiaWire.nonce(random,System.currentTimeMillis()),security=session.getString("ssecurity");
            Map<String,String> headers=new LinkedHashMap<>();headers.put("Content-Type","application/x-www-form-urlencoded");headers.put("MIOT-ENCRYPT-ALGORITHM","ENCRYPT-RC4");headers.put("x-xiaomi-protocal-flag-cli","PROTOCAL-HTTP2");headers.put("User-Agent","Android-16-HomeControl APP/xiaomi.smarthome APPV/62830");headers.put("Cookie","userId="+session.getString("userId")+"; serviceToken="+session.getString("serviceToken")+"; yetAnotherServiceToken="+session.getString("serviceToken"));String host=new java.net.URI(base).getHost();
            MijiaHttp.Reply r=new MijiaHttp().request(base+path,MijiaWire.form(MijiaWire.encrypt(path,query.toString(),security,nonce)),headers,null,u->MijiaWire.secure(u)&&host.equals(u.getHost()),4194304,15000);report.putInt("recipe_http",r.code);if(r.code!=200)return;
            JSONObject data=new JSONObject(r.body.trim().startsWith("{")?r.body:MijiaWire.decrypt(security,nonce,r.body));report.putInt("recipe_api_code",data.optInt("code",Integer.MIN_VALUE));report.putString("recipe_root_keys",new JSONArray(data.names()==null?Collections.emptyList():jsonStrings(data.names())).toString());List<String> names=new ArrayList<>();recipeNames(data,names,0);report.putInt("recipe_name_count",names.size());report.putString("recipe_names",new JSONArray(names.subList(0,Math.min(3,names.size()))).toString());
        }
    }
    private List<String> jsonStrings(JSONArray a){List<String> out=new ArrayList<>();for(int i=0;i<a.length();i++)out.add(a.optString(i));return out;}
    private boolean safe(String k){return !k.toLowerCase(java.util.Locale.ROOT).matches(".*(deviceid|deviceno|did|mac|userid|uid|token|secret|signature|password|account|authed|identify).* ".trim())&&k.matches("[A-Za-z][A-Za-z0-9_-]{0,60}");}
    private String shape(Object x,int depth)throws Exception{if(depth>5)return "...";if(x instanceof JSONObject){JSONObject out=new JSONObject();Iterator<String> i=((JSONObject)x).keys();int n=0;while(i.hasNext()&&n++<45){String k=i.next();if(safe(k))out.put(k,shape(((JSONObject)x).opt(k),depth+1));}return out.toString();}if(x instanceof JSONArray){JSONArray a=(JSONArray)x;return "array("+a.length()+")"+(a.length()>0?shape(a.opt(0),depth+1):"");}return x==null?"null":x.getClass().getSimpleName();}
    private JSONObject sample(Object x,int depth)throws Exception{JSONObject out=new JSONObject();if(depth>6)return out;if(x instanceof JSONObject){JSONObject o=(JSONObject)x;for(Iterator<String> i=o.keys();i.hasNext();){String k=i.next();Object v=o.opt(k);if(!safe(k))continue;if(v instanceof String&&(((String)v).startsWith("{")||((String)v).startsWith("["))){try{v=new JSONTokener((String)v).nextValue();}catch(Exception ignored){continue;}}if(Arrays.asList("code","status","message","msg","name","recipeName","id","recipeId","bussinessId","menuType","menuId","data","cookData","cookcode","cookScript","recipeCommand","cookTime","tCook","type","time","minTime","maxTime","timeEditable","unit","fire","fireEditable","weight","minWeight","maxWeight","weightEditable","weightUnit").contains(k)&&!(v instanceof JSONObject)&&!(v instanceof JSONArray)&&String.valueOf(v).length()<700)out.put(k,v);else if(v instanceof JSONObject||v instanceof JSONArray){JSONObject child=sample(v,depth+1);if(child.length()>0)out.put(k,child);}}}else if(x instanceof JSONArray){JSONArray a=(JSONArray)x;for(int i=0;i<Math.min(2,a.length());i++){JSONObject child=sample(a.opt(i),depth+1);if(child.length()>0)out.put("item"+i,child);}}return out;}
    private void recipeNames(Object value,List<String> out,int depth)throws Exception{if(depth>12||out.size()>100)return;if(value instanceof JSONObject){JSONObject o=(JSONObject)value;for(Iterator<String> keys=o.keys();keys.hasNext();){String key=keys.next();Object v=o.opt(key);if(("recipeName".equals(key)||"recipe_name".equals(key)||"name".equals(key))&&v instanceof String&&((String)v).length()<80)out.add((String)v);else recipeNames(v,out,depth+1);}}else if(value instanceof JSONArray){JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++)recipeNames(a.opt(i),out,depth+1);}else if(value instanceof String&&(((String)value).startsWith("{")||((String)value).startsWith("[")))try{recipeNames(new JSONTokener((String)value).nextValue(),out,depth+1);}catch(JSONException ignored){}}
}
